// IndexedDB 저장소 설정
import { openDB } from 'idb';
import type { DBSchema, IDBPDatabase } from 'idb';
import type { 
  ScheduleEvent, 
  RecurringEvent, 
  TodoItem, 
  DaySummary, 
  AppSettings,
  SyncState,
} from '../types';

interface MyScheduleDB extends DBSchema {
  settings: {
    key: string;
    value: AppSettings;
  };
  days: {
    key: string;
    value: DaySummary;
    indexes: { 'by-date': string };
  };
  events: {
    key: string;
    value: ScheduleEvent;
    indexes: { 'by-date': string };
  };
  recurringEvents: {
    key: string;
    value: RecurringEvent;
  };
  todos: {
    key: string;
    value: TodoItem;
    indexes: { 'by-date': string };
  };
  sync: {
    key: string;
    value: SyncState;
  };
}

const DB_NAME = 'myschedul-db';
const DB_VERSION = 1;

let dbInstance: IDBPDatabase<MyScheduleDB> | null = null;

export async function getDB(): Promise<IDBPDatabase<MyScheduleDB>> {
  if (dbInstance) return dbInstance;

  dbInstance = await openDB<MyScheduleDB>(DB_NAME, DB_VERSION, {
    upgrade(db) {
      // Settings store
      if (!db.objectStoreNames.contains('settings')) {
        db.createObjectStore('settings');
      }

      // Days store
      if (!db.objectStoreNames.contains('days')) {
        const daysStore = db.createObjectStore('days', { keyPath: 'date' });
        daysStore.createIndex('by-date', 'date');
      }

      // Events store
      if (!db.objectStoreNames.contains('events')) {
        const eventsStore = db.createObjectStore('events', { keyPath: 'id' });
        eventsStore.createIndex('by-date', 'date');
      }

      // Recurring events store
      if (!db.objectStoreNames.contains('recurringEvents')) {
        db.createObjectStore('recurringEvents', { keyPath: 'id' });
      }

      // Todos store
      if (!db.objectStoreNames.contains('todos')) {
        const todosStore = db.createObjectStore('todos', { keyPath: 'id' });
        todosStore.createIndex('by-date', 'date');
      }

      // Sync store
      if (!db.objectStoreNames.contains('sync')) {
        db.createObjectStore('sync');
      }
    },
  });

  return dbInstance;
}

// 유틸리티 함수들
export function generateId(): string {
  return `${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}
