// 반복 일정 로직
import { addDays, addMonths, format, parse, isAfter, isBefore, getDay } from 'date-fns';
import type { RecurringEvent, ScheduleEvent, RecurrenceRule } from '../types';
import { generateId } from '../stores/db';

const DAY_MAP: Record<string, number> = {
  sun: 0,
  mon: 1,
  tue: 2,
  wed: 3,
  thu: 4,
  fri: 5,
  sat: 6,
};

/**
 * 반복 규칙에 따라 특정 날짜에 해당하는 이벤트 인스턴스 생성
 */
export function generateRecurringInstances(
  recurringEvent: RecurringEvent,
  startDate: string, // YYYY-MM-DD
  endDate: string    // YYYY-MM-DD
): ScheduleEvent[] {
  const instances: ScheduleEvent[] = [];
  const { rule } = recurringEvent;
  
  const rangeStart = parse(startDate, 'yyyy-MM-dd', new Date());
  const rangeEnd = parse(endDate, 'yyyy-MM-dd', new Date());
  const ruleStart = parse(rule.startDate, 'yyyy-MM-dd', new Date());
  const ruleEnd = rule.endDate ? parse(rule.endDate, 'yyyy-MM-dd', new Date()) : null;

  // 시작일 결정
  let currentDate = isBefore(ruleStart, rangeStart) ? rangeStart : ruleStart;
  
  // 종료일 결정
  const effectiveEnd = ruleEnd && isBefore(ruleEnd, rangeEnd) ? ruleEnd : rangeEnd;

  while (!isAfter(currentDate, effectiveEnd)) {
    if (shouldGenerateOnDate(currentDate, rule)) {
      const dateStr = format(currentDate, 'yyyy-MM-dd');
      
      instances.push({
        id: `${recurringEvent.id}_${dateStr}`,
        date: dateStr,
        start: recurringEvent.start,
        end: recurringEvent.end,
        title: recurringEvent.title,
        color: recurringEvent.color,
        note: recurringEvent.note,
        status: 'planned',
        recurrenceId: recurringEvent.id,
        createdAt: recurringEvent.createdAt,
        updatedAt: recurringEvent.updatedAt,
      });
    }

    // 다음 날짜로 이동
    currentDate = getNextDate(currentDate, rule);
  }

  return instances;
}

/**
 * 특정 날짜에 반복 이벤트가 발생해야 하는지 확인
 */
function shouldGenerateOnDate(date: Date, rule: RecurrenceRule): boolean {
  switch (rule.frequency) {
    case 'daily':
      return true;
      
    case 'weekly':
      if (!rule.days || rule.days.length === 0) return false;
      const dayOfWeek = getDay(date);
      return rule.days.some(day => DAY_MAP[day] === dayOfWeek);
      
    case 'monthly':
      if (!rule.dayOfMonth) return false;
      return date.getDate() === rule.dayOfMonth;
      
    default:
      return false;
  }
}

/**
 * 다음 확인할 날짜 계산
 */
function getNextDate(currentDate: Date, rule: RecurrenceRule): Date {
  switch (rule.frequency) {
    case 'daily':
      return addDays(currentDate, rule.interval);
      
    case 'weekly':
      // weekly는 매일 확인하고 shouldGenerateOnDate에서 필터링
      return addDays(currentDate, 1);
      
    case 'monthly':
      return addMonths(currentDate, rule.interval);
      
    default:
      return addDays(currentDate, 1);
  }
}

/**
 * 특정 날짜의 반복 이벤트 인스턴스들 가져오기
 */
export function getRecurringEventsForDate(
  recurringEvents: RecurringEvent[],
  date: string
): ScheduleEvent[] {
  const instances: ScheduleEvent[] = [];
  
  for (const recurring of recurringEvents) {
    const dayInstances = generateRecurringInstances(recurring, date, date);
    instances.push(...dayInstances);
  }
  
  return instances;
}

/**
 * 새 반복 이벤트 생성
 */
export function createRecurringEvent(
  title: string,
  start: string,
  end: string,
  color: string,
  note: string,
  rule: RecurrenceRule
): RecurringEvent {
  return {
    id: generateId(),
    title,
    start,
    end,
    color,
    note,
    rule,
    createdAt: Date.now(),
    updatedAt: Date.now(),
  };
}
